//! Scalar values: the fixed single-value kinds (integers, floats, bool, string,
//! raw binary). The per-type families are generated by `macro_rules!`.

use std::ffi::c_void;

use fon::types::FonValue;
use fon::RawData;

use crate::collection::{put_field, read_as};
use crate::error::{finish, slice_arg, str_arg, write_out, write_sized, Failure, FonError};


macro_rules! put_scalar {
    ($name:ident, $ty:ty, $variant:ident) => {
        #[no_mangle]
        pub extern "C" fn $name(
            collection: *mut c_void,
            key: *const u8,
            key_len: i64,
            value: $ty,
            mode: i32,
            error: *mut FonError,
        ) -> i32 {
            let result: Result<(), Failure> = unsafe {
                put_field(collection, key, key_len, mode, || Ok(FonValue::$variant(value)))
            };
            unsafe { finish(error, result) }
        }
    };
}


macro_rules! get_scalar {
    ($name:ident, $ty:ty, $variant:ident, $expected:literal) => {
        #[no_mangle]
        pub extern "C" fn $name(
            collection: *mut c_void,
            key: *const u8,
            key_len: i64,
            out: *mut $ty,
            error: *mut FonError,
        ) -> i32 {
            let result: Result<(), Failure> = unsafe {
                read_as(collection, key, key_len, $expected, |value| match value {
                    FonValue::$variant(picked) => Some(*picked),
                    _ => None,
                })
                .and_then(|picked| write_out(out, picked))
            };
            unsafe { finish(error, result) }
        }
    };
}


put_scalar!(fon_collection_put_byte, u8, Byte);
put_scalar!(fon_collection_put_short, i16, Short);
put_scalar!(fon_collection_put_int, i32, Int);
put_scalar!(fon_collection_put_uint, u32, UInt);
put_scalar!(fon_collection_put_long, i64, Long);
put_scalar!(fon_collection_put_ulong, u64, ULong);
put_scalar!(fon_collection_put_float, f32, Float);
put_scalar!(fon_collection_put_double, f64, Double);

get_scalar!(fon_collection_get_byte, u8, Byte, "byte");
get_scalar!(fon_collection_get_short, i16, Short, "short");
get_scalar!(fon_collection_get_int, i32, Int, "int");
get_scalar!(fon_collection_get_uint, u32, UInt, "uint");
get_scalar!(fon_collection_get_long, i64, Long, "long");
get_scalar!(fon_collection_get_ulong, u64, ULong, "ulong");
get_scalar!(fon_collection_get_float, f32, Float, "float");
get_scalar!(fon_collection_get_double, f64, Double, "double");


#[no_mangle]
pub extern "C" fn fon_collection_put_bool(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    value: i32,
    mode: i32,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        put_field(collection, key, key_len, mode, || Ok(FonValue::Bool(value != 0)))
    };
    unsafe { finish(error, result) }
}


#[no_mangle]
pub extern "C" fn fon_collection_get_bool(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    out: *mut i32,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        read_as(collection, key, key_len, "bool", |value| match value {
            FonValue::Bool(picked) => Some(*picked),
            _ => None,
        })
        .and_then(|picked| write_out(out, i32::from(picked)))
    };
    unsafe { finish(error, result) }
}


#[no_mangle]
pub extern "C" fn fon_collection_put_string(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    value: *const u8,
    value_len: i64,
    mode: i32,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        put_field(collection, key, key_len, mode, || -> Result<FonValue, Failure> {
            Ok(FonValue::String(str_arg(value, value_len)?.to_owned()))
        })
    };
    unsafe { finish(error, result) }
}


#[no_mangle]
pub extern "C" fn fon_collection_put_raw(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    data: *const u8,
    data_len: i64,
    mode: i32,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        put_field(collection, key, key_len, mode, || -> Result<FonValue, Failure> {
            let bytes: Vec<u8> = slice_arg(data, data_len)?.to_vec();
            Ok(FonValue::Raw(Box::new(RawData::from_bytes(bytes))))
        })
    };
    unsafe { finish(error, result) }
}


#[no_mangle]
pub extern "C" fn fon_collection_get_string(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    buffer: *mut u8,
    capacity: i64,
    actual: *mut i64,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        read_as(collection, key, key_len, "string", |value| match value {
            FonValue::String(picked) => Some(picked.as_bytes()),
            _ => None,
        })
        .and_then(|bytes| write_sized(bytes, buffer, capacity, actual))
    };
    unsafe { finish(error, result) }
}


#[no_mangle]
pub extern "C" fn fon_collection_get_raw(
    collection: *mut c_void,
    key: *const u8,
    key_len: i64,
    buffer: *mut u8,
    capacity: i64,
    actual: *mut i64,
    error: *mut FonError,
) -> i32 {
    let result: Result<(), Failure> = unsafe {
        read_as(collection, key, key_len, "raw", |value| match value {
            FonValue::Raw(picked) => Some(&**picked),
            _ => None,
        })
        .and_then(decode_raw)
        .and_then(|bytes| write_sized(bytes.as_slice(), buffer, capacity, actual))
    };
    unsafe { finish(error, result) }
}


/// Returns the decoded payload of a raw value, unpacking Z85 text when needed.
fn decode_raw(raw: &RawData) -> Result<Vec<u8>, Failure> {
    if raw.is_unpacked() {
        return Ok(raw.data().to_vec());
    }
    if raw.is_packed() {
        let mut decoded: RawData = RawData::from_encoded(raw.encoded().to_owned());
        decoded.unpack()?;
        return Ok(decoded.data().to_vec());
    }
    Ok(Vec::new())
}
